// Evaluate Meta's GET webhook verification handshake.
//
// The verify token itself is never read here -- only an HMAC "commitment"
// (EXPECTED_COMMITMENT, computed once at setup time with
// scripts/generate_webhook_verify_commitment.py) is compared against an
// HMAC computed over the incoming hub.verify_token using the real secret
// via the bound "crypto" credential (see the "Hash GET Verify Token" node).
// If the incoming token matches the real secret, the two HMACs are equal;
// if not, they differ.
//
// This commitment is a ONE-WAY function of the token, but it is still a
// DETERMINISTIC function of the token: by itself it does not prove the
// token has enough entropy to resist offline guessing of the token from
// the commitment. Use only a cryptographically random token with at least
// 256 bits of entropy (the setup script generates one for you). See the
// workflow documentation's "Security design" section for the full
// explanation of what this commitment does and does not protect against.

function timingSafeEqualHex(a, b) {
  if (typeof a !== 'string' || typeof b !== 'string') return false;
  if (a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) {
    diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  }
  return diff === 0;
}

function isValidCommitmentFormat(value) {
  return typeof value === 'string' && /^[0-9a-f]{64}$/.test(value);
}

// UNCONFIGURED PLACEHOLDER. Replace with the commitment printed by
// scripts/generate_webhook_verify_commitment.py after creating your own
// "Verify Token" credential -- see the documentation's setup steps. Until
// replaced with a valid 64-character lowercase hex value, this workflow
// FAILS CLOSED: every GET verification request is rejected, regardless of
// the incoming hub.verify_token or hub.mode.
const EXPECTED_COMMITMENT = 'REPLACE_WITH_YOUR_COMMITMENT__SEE_SETUP_STEP_3';

const commitmentConfigured = isValidCommitmentFormat(EXPECTED_COMMITMENT);

const trigger = $('GET Trigger').first().json;
const mode = trigger.query && trigger.query['hub.mode'];
const challenge = trigger.query && trigger.query['hub.challenge'];
const computedHash = $input.first().json.incomingHash;

const modeOk = mode === 'subscribe';
const tokenOk = commitmentConfigured && timingSafeEqualHex(computedHash, EXPECTED_COMMITMENT);
const verified = commitmentConfigured && modeOk && tokenOk;

return [{ json: { verified: verified ? 'yes' : 'no', challenge: verified && typeof challenge === 'string' ? challenge : '' } }];

// Validate Meta's X-Hub-Signature-256 header against an HMAC-SHA256 of the
// EXACT raw request body (never a re-parsed/re-serialized copy -- the
// Webhook trigger's "Raw Body" option preserves the original bytes exactly,
// and the "Compute POST Body HMAC" node hashes that binary data directly).

function timingSafeEqualHex(a, b) {
  if (typeof a !== 'string' || typeof b !== 'string') return false;
  if (a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) {
    diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  }
  return diff === 0;
}

const trigger = $('POST Trigger').first().json;
const headers = trigger.headers || {};
const signatureHeader = headers['x-hub-signature-256'];
const computedHex = $input.first().json.bodyHmac;

let verified = false;
if (typeof signatureHeader === 'string' && signatureHeader.startsWith('sha256=')) {
  const providedHex = signatureHeader.slice('sha256='.length).toLowerCase();
  verified = timingSafeEqualHex(providedHex, computedHex);
}

return [{ json: { verified: verified ? 'yes' : 'no' } }];
